/**
 * LadiPage SDK Stub & Compatibility Runtime
 * Apex CRM Multi-Landing Platform
 */
(function(window) {
    'use strict';
    window.ladi = window.ladi || {};
    window.LadiPage = window.LadiPage || window.ladi;
    window.ladihtml = window.ladihtml || window.ladi;

    if (!window.ladi.isInit) {
        window.ladi.isInit = true;
        window.ladi.version = '1.0.0-compat';
        window.ladi.events = window.ladi.events || {};
        window.ladi.on = function(evt, cb) {
            window.ladi.events[evt] = window.ladi.events[evt] || [];
            window.ladi.events[evt].push(cb);
        };
        window.ladi.trigger = function(evt, data) {
            if (window.ladi.events[evt]) {
                window.ladi.events[evt].forEach(function(fn) {
                    try { fn(data); } catch (e) { console.warn('[LadiSDK Error]', e); }
                });
            }
        };
        window.ladi.init = function() {
            window.ladi.trigger('ready');
        };
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', function() { window.ladi.init(); });
        } else {
            window.ladi.init();
        }
    }
})(window);
